mapper.insert:
insert into phone_one_tap_rate_buckets (
    request_ip, bucket_type, bucket_start, request_count
) values (
    #{requestIp}, #{bucketType}, #{bucketStart}, 0
)
on duplicate key update request_count = request_count

mapper.select:
select request_count
from phone_one_tap_rate_buckets
where request_ip = #{requestIp}
  and bucket_type = #{bucketType}
  and bucket_start = #{bucketStart}
for update

mapper.update:
update phone_one_tap_rate_buckets
set request_count = request_count + 1, update_time = now()
where request_ip = #{requestIp}
  and bucket_type = #{bucketType}
  and bucket_start = #{bucketStart}

mapper.delete:
delete from phone_one_tap_rate_buckets
where bucket_start < #{cutoff}
order by bucket_start
limit #{limit}
